examples.code:
client = mcpConnect(
      transport = "stdio"
    , command   = "npx -y @modelcontextprotocol/server-filesystem /tmp"
);

tools = client.tools();
rows  = client.call( "read_file", { path = "/tmp/notes.txt" } );
client.close();

client = mcpConnect(
      transport = "http"
    , url       = "https://example.com/mcp"
    , headers   = { Authorization = "Bearer #token#" }
);

tools = client.tools();
result = client.call( "search", { query = "invoices" } );
client.close();
